class Edge {

	private int startNode, endNode, weight;

	public Edge(int startNode, int endNode, int weight) {
		this.startNode = startNode;
		this.endNode = endNode;
		this.weight = weight;
	}

	public int getStartNode() {
		return startNode;
	}

	public int getEndNode() {
